"""Regenerate the pre-0001 schema snapshots in this directory.

`tenant.sql` and `control.sql` are the schemas a tenant database and a control
plane had on the day before the first Alembic revision (`0001_signup`, commit
f6d93ab1) — the shape every database that predates Alembic started from, and
the starting point `tests/test_schema_build_parity.py` runs the whole chain
over. They are a historical record, so they should never need regenerating;
this script exists so the snapshot can be re-derived and checked rather than
taken on trust.

At that commit the schema was built by ``create_all`` alone:

* the control plane by ``Base.metadata.create_all`` of EVERY model
  (`scripts/seed.py::create_control_tables`), tenant tables included;
* a tenant database by ``create_all`` of every model except the four control
  tables (`scripts/create_tenant.py::create_tenant_tables`).

Usage, from the repository root::

    mkdir -p /tmp/pre0001
    git archive f6d93ab1^ backend/app/__init__.py backend/app/models | tar -x -C /tmp/pre0001
    backend/.venv/bin/python -I backend/tests/fixtures/pre_0001_schema/generate.py \\
        /tmp/pre0001/backend backend/tests/fixtures/pre_0001_schema

The archived tree is put FIRST on ``sys.path`` before ``app`` is imported, and
``-I`` keeps the current checkout (cwd, ``PYTHONPATH``) off it, so the CURRENT
models cannot shadow the archived ones. They import nothing but SQLAlchemy.
"""

from __future__ import annotations

import sys
from pathlib import Path

from sqlalchemy import create_mock_engine

COMMIT = "f6d93ab1^"
# scripts/create_tenant.py at that commit.
CONTROL_TABLES = {"organizations", "users", "roles", "user_roles"}


def _ddl(Base, tables) -> str:
    statements: list[str] = []

    def dump(sql, *_args, **_kw):
        statements.append(str(sql.compile(dialect=engine.dialect)).strip() + ";")

    engine = create_mock_engine("postgresql+psycopg2://", dump)
    Base.metadata.create_all(engine, tables=tables, checkfirst=False)
    return "\n\n".join(statements) + "\n"


def main(models_root: Path, out_dir: Path) -> None:
    sys.path.insert(0, str(models_root))
    import importlib

    from app.models import Base  # the ARCHIVED models

    assert Path(sys.modules["app.models"].__file__).resolve().is_relative_to(models_root.resolve())
    # Every model module, not just what `app/models/__init__.py` re-exported:
    # `gl_account` and `virtual_card` (GLAccount, VirtualCard, CardRebate) were
    # not in it yet, but `seed.py` and the routers imported them, so the
    # `create_all` that built every pre-0001 database included their tables.
    for module in sorted((models_root / "app" / "models").glob("*.py")):
        if module.stem != "__init__":
            importlib.import_module(f"app.models.{module.stem}")
    header = (
        f"-- Generated by generate.py from the models at {COMMIT} (the day before\n"
        "-- Alembic revision 0001_signup). Historical snapshot: do not edit.\n\n"
    )
    all_tables = list(Base.metadata.sorted_tables)
    tenant_tables = [t for t in all_tables if t.name not in CONTROL_TABLES]
    (out_dir / "control.sql").write_text(header + _ddl(Base, all_tables))
    (out_dir / "tenant.sql").write_text(header + _ddl(Base, tenant_tables))


if __name__ == "__main__":
    main(Path(sys.argv[1]), Path(sys.argv[2]))
